-- O-38 (onprem/REGISTER.md) — Referenzdaten für die Box: Kostenträger (IK-Verzeichnis).
--
-- Kutuya seed. Kaynak: GKV Kostenträgerdatei (parser.js ile 06.09.2026'da yerleşen
-- gerçek dosyalar), üretici: tools/seed-generieren.mjs (deterministik ORDER BY ik).
-- Yalnız datensatz_status='echt' satırlar — 9 mock kalıntı (üretim/geliştirme
-- amaçlı, canlıda hiç FK'sı olmayan IK'lar) bilinçli olarak dışarıda bırakıldı
-- (onprem-review + db-ustasi, 12.09.2026).
--
-- ON CONFLICT (ik) DO UPDATE: checksum kilidi bu dosyayı bir daha çalıştırmaz, ama
-- SaaS'ta bu veri ZATEN var — G7 (tek codebase, iki dağıtım) bu dosyanın SaaS'a
-- karşı da hatasız çalışmasını ister. INSERT tek başına orada PK çakışmasıyla patlardı.
--
-- DELETE YOK (SEED-3): kostentraeger_annahmestellen ve heilmittel_tarif buraya
-- ON DELETE CASCADE ile bağlı; bir satırın silinmesi başka tabloları da götürürdü.
-- Düşen bir kasa varsa gelecek bir migration onu active=false ile pasifleştirir.

ON CONFLICT (ik) DO UPDATE SET
  name=EXCLUDED.name, das_ik=EXCLUDED.das_ik, payer_type=EXCLUDED.payer_type, region=EXCLUDED.region,
  active=EXCLUDED.active, valid_from=EXCLUDED.valid_from, valid_to=EXCLUDED.valid_to, updated_at=EXCLUDED.updated_at,
  kurzname=EXCLUDED.kurzname, abrechnender_kt_ik=EXCLUDED.abrechnender_kt_ik, ist_abrechnender_kt=EXCLUDED.ist_abrechnender_kt,
  quelle=EXCLUDED.quelle, quelle_stand=EXCLUDED.quelle_stand, datensatz_status=EXCLUDED.datensatz_status;

ON CONFLICT (ik) DO UPDATE SET
  name=EXCLUDED.name, das_ik=EXCLUDED.das_ik, payer_type=EXCLUDED.payer_type, region=EXCLUDED.region,
  active=EXCLUDED.active, valid_from=EXCLUDED.valid_from, valid_to=EXCLUDED.valid_to, updated_at=EXCLUDED.updated_at,
  kurzname=EXCLUDED.kurzname, abrechnender_kt_ik=EXCLUDED.abrechnender_kt_ik, ist_abrechnender_kt=EXCLUDED.ist_abrechnender_kt,
  quelle=EXCLUDED.quelle, quelle_stand=EXCLUDED.quelle_stand, datensatz_status=EXCLUDED.datensatz_status;

ON CONFLICT (ik) DO UPDATE SET
  name=EXCLUDED.name, das_ik=EXCLUDED.das_ik, payer_type=EXCLUDED.payer_type, region=EXCLUDED.region,
  active=EXCLUDED.active, valid_from=EXCLUDED.valid_from, valid_to=EXCLUDED.valid_to, updated_at=EXCLUDED.updated_at,
  kurzname=EXCLUDED.kurzname, abrechnender_kt_ik=EXCLUDED.abrechnender_kt_ik, ist_abrechnender_kt=EXCLUDED.ist_abrechnender_kt,
  quelle=EXCLUDED.quelle, quelle_stand=EXCLUDED.quelle_stand, datensatz_status=EXCLUDED.datensatz_status;
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.kostentraeger WHERE datensatz_status='echt';
  IF n < 1043 THEN RAISE EXCEPTION 'seed kostentraeger: % Zeilen (echt), erwartet >= 1043', n; END IF;
END $$;
